-- Direct-method cash flow is a read-only projection; classifications never post money.
CREATE TABLE accounting.cash_flow_scopes(
 company_id uuid NOT NULL REFERENCES core.companies(id),bank_account_id uuid NOT NULL,included boolean NOT NULL,review_required boolean NOT NULL DEFAULT false,reason text NOT NULL CHECK(length(btrim(reason)) BETWEEN 1 AND 2000),version bigint NOT NULL DEFAULT 1,updated_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(company_id,bank_account_id),FOREIGN KEY(company_id,bank_account_id) REFERENCES accounting.bank_accounts(company_id,id));
CREATE TABLE accounting.cash_flow_classifications(
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(),company_id uuid NOT NULL REFERENCES core.companies(id),journal_entry_id uuid NOT NULL,revision bigint NOT NULL CHECK(revision>0),mode text NOT NULL CHECK(mode IN('AUTO','CUSTOM')),reason text NOT NULL CHECK(length(btrim(reason)) BETWEEN 1 AND 2000),created_at timestamptz NOT NULL DEFAULT now(),created_by uuid NOT NULL REFERENCES identity.users(id),UNIQUE(company_id,id),UNIQUE(company_id,journal_entry_id,revision),FOREIGN KEY(company_id,journal_entry_id) REFERENCES accounting.journal_entries(company_id,id));
CREATE TABLE accounting.cash_flow_allocations(
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(),company_id uuid NOT NULL REFERENCES core.companies(id),classification_id uuid NOT NULL,journal_line_id uuid NOT NULL,category text NOT NULL CHECK(category IN('OPERATING','INVESTING','FINANCING','INTERNAL')),amount numeric(20,2) NOT NULL CHECK(amount>0),UNIQUE(company_id,id),UNIQUE(company_id,classification_id,journal_line_id,category),FOREIGN KEY(company_id,classification_id) REFERENCES accounting.cash_flow_classifications(company_id,id),FOREIGN KEY(company_id,journal_line_id) REFERENCES accounting.journal_lines(company_id,id));
DO $$ DECLARE t text;BEGIN FOREACH t IN ARRAY ARRAY['cash_flow_scopes','cash_flow_classifications','cash_flow_allocations'] LOOP EXECUTE format('ALTER TABLE accounting.%I ENABLE ROW LEVEL SECURITY',t);EXECUTE format('ALTER TABLE accounting.%I FORCE ROW LEVEL SECURITY',t);EXECUTE format('CREATE POLICY company_scope ON accounting.%I USING(company_id=core.current_company()) WITH CHECK(company_id=core.current_company())',t);IF t<>'cash_flow_scopes' THEN EXECUTE format('CREATE TRIGGER append_only BEFORE UPDATE OR DELETE ON accounting.%I FOR EACH ROW EXECUTE FUNCTION platform.reject_mutation()',t);END IF;END LOOP;END $$;
CREATE TRIGGER touch_version BEFORE UPDATE ON accounting.cash_flow_scopes FOR EACH ROW EXECUTE FUNCTION core.touch_version();
INSERT INTO identity.permissions(code,description) VALUES('accounting.cash_flow.classify','Classify cash flow with immutable revisions'),('accounting.cash_flow.configure','Configure cash-equivalent scope before use');
CREATE FUNCTION identity.seed_cash_flow_roles(c uuid) RETURNS void LANGUAGE plpgsql SET search_path=pg_catalog AS $$ BEGIN INSERT INTO identity.role_permissions(company_id,role_id,permission_code) SELECT c,r.id,p.code FROM identity.roles r CROSS JOIN identity.permissions p WHERE r.company_id=c AND r.code IN('ADMIN','FINANCE') AND p.code IN('accounting.cash_flow.classify','accounting.cash_flow.configure') ON CONFLICT DO NOTHING;END $$;
DO $$ DECLARE c uuid;BEGIN FOR c IN SELECT id FROM core.companies LOOP PERFORM set_config('htt.company_id',c::text,true);PERFORM identity.seed_cash_flow_roles(c);INSERT INTO accounting.cash_flow_scopes(company_id,bank_account_id,included,review_required,reason) SELECT c,b.id,b.kind<>'CARD_CLEARING',EXISTS(SELECT 1 FROM accounting.journal_lines l WHERE l.company_id=c AND l.account_id=b.id),'Initial cash scope: BANK/CASH/LEGACY included; card clearing excluded' FROM accounting.bank_accounts b WHERE b.company_id=c;END LOOP;PERFORM set_config('htt.company_id','',true);END $$;
CREATE FUNCTION accounting.synchronize_cash_scope() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$ BEGIN
 IF TG_OP='INSERT' THEN INSERT INTO accounting.cash_flow_scopes(company_id,bank_account_id,included,reason) VALUES(NEW.company_id,NEW.id,NEW.kind<>'CARD_CLEARING','Initial cash account scope');
 ELSIF OLD.kind IS DISTINCT FROM NEW.kind AND (OLD.kind='CARD_CLEARING')<>(NEW.kind='CARD_CLEARING') THEN
 PERFORM 1 FROM accounting.cash_flow_scopes WHERE company_id=NEW.company_id AND bank_account_id=NEW.id FOR UPDATE;
 IF EXISTS(SELECT 1 FROM accounting.journal_lines WHERE company_id=NEW.company_id AND account_id=NEW.id) AND EXISTS(SELECT 1 FROM accounting.cash_flow_scopes WHERE company_id=NEW.company_id AND bank_account_id=NEW.id AND included IS DISTINCT FROM(NEW.kind<>'CARD_CLEARING')) THEN RAISE EXCEPTION 'Used cash-equivalent scope is immutable; create a new account' USING ERRCODE='HR409';END IF;
 UPDATE accounting.cash_flow_scopes SET included=NEW.kind<>'CARD_CLEARING',reason='Initial directory kind configured before first use' WHERE company_id=NEW.company_id AND bank_account_id=NEW.id;END IF;RETURN NULL;END $$;
CREATE TRIGGER synchronize_cash_scope AFTER INSERT OR UPDATE ON accounting.bank_accounts FOR EACH ROW EXECUTE FUNCTION accounting.synchronize_cash_scope();
CREATE FUNCTION accounting.freeze_used_cash_scope() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$ BEGIN IF NEW.review_required AND NOT OLD.review_required THEN RAISE EXCEPTION 'Reviewed cash scope cannot return to pending' USING ERRCODE='HR409';END IF;IF NEW.included<>OLD.included AND NOT OLD.review_required AND EXISTS(SELECT 1 FROM accounting.journal_lines WHERE company_id=OLD.company_id AND account_id=OLD.bank_account_id) THEN RAISE EXCEPTION 'Used cash-equivalent scope is immutable' USING ERRCODE='HR409';END IF;RETURN NEW;END $$;
CREATE TRIGGER freeze_used_cash_scope BEFORE UPDATE ON accounting.cash_flow_scopes FOR EACH ROW EXECUTE FUNCTION accounting.freeze_used_cash_scope();
CREATE TRIGGER retain_cash_scope BEFORE DELETE ON accounting.cash_flow_scopes FOR EACH ROW EXECUTE FUNCTION platform.reject_mutation();
REVOKE ALL ON FUNCTION accounting.freeze_used_cash_scope() FROM PUBLIC;
CREATE FUNCTION accounting.require_cash_flow_access(permission text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$ BEGIN PERFORM purchase.require_access('accounting.reports.read');PERFORM purchase.require_access('accounting.ledger.read');PERFORM purchase.require_access('accounting.banks.read');IF permission<>'accounting.reports.read' THEN PERFORM purchase.require_access(permission);END IF;END $$;
CREATE FUNCTION accounting.configure_cash_scope(bank uuid,expected bigint,p_included boolean,p_reason text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$ DECLARE x accounting.cash_flow_scopes;BEGIN
 PERFORM accounting.require_cash_flow_access('accounting.cash_flow.configure');SELECT * INTO x FROM accounting.cash_flow_scopes WHERE company_id=core.current_company() AND bank_account_id=bank FOR UPDATE;IF NOT FOUND THEN RAISE EXCEPTION 'Cash scope unavailable' USING ERRCODE='HT404';END IF;
 IF expected IS NULL OR expected<>x.version THEN RAISE EXCEPTION 'Cash scope changed' USING ERRCODE='HR409';END IF;
 IF p_included IS NULL OR p_reason IS NULL OR length(btrim(p_reason)) NOT BETWEEN 1 AND 2000 THEN RAISE EXCEPTION 'Scope and reason required' USING ERRCODE='HR422';END IF;
 IF x.included<>p_included AND NOT x.review_required AND EXISTS(SELECT 1 FROM accounting.journal_lines WHERE company_id=x.company_id AND account_id=bank) THEN RAISE EXCEPTION 'Used cash-equivalent scope is immutable; create a new account' USING ERRCODE='HR409';END IF;
 UPDATE accounting.cash_flow_scopes SET included=p_included,review_required=false,reason=btrim(p_reason) WHERE company_id=x.company_id AND bank_account_id=bank;END $$;
CREATE FUNCTION accounting.guard_cash_scope_posting() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$ DECLARE x record;BEGIN
 FOR x IN SELECT DISTINCT n.company_id,n.account_id FROM cash_scope_inserted n JOIN accounting.accounts a ON a.company_id=n.company_id AND a.id=n.account_id WHERE a.control_kind='BANK' ORDER BY n.company_id,n.account_id LOOP
 PERFORM 1 FROM accounting.cash_flow_scopes WHERE company_id=x.company_id AND bank_account_id=x.account_id FOR SHARE;IF NOT FOUND THEN RAISE EXCEPTION 'Cash scope missing' USING ERRCODE='HR409';END IF;END LOOP;RETURN NULL;END $$;
CREATE TRIGGER cash_scope_posting_guard AFTER INSERT ON accounting.journal_lines REFERENCING NEW TABLE AS cash_scope_inserted FOR EACH STATEMENT EXECUTE FUNCTION accounting.guard_cash_scope_posting();
CREATE VIEW accounting.cash_flow_lines WITH(security_invoker=true) AS
 SELECT l.company_id,l.id,l.account_id AS bank_account_id,l.journal_entry_id,l.debit-l.credit AS signed_amount,abs(l.debit-l.credit) AS amount,j.posting_date,j.description,b.source_document_id,b.posting_kind,d.number AS source_number,
 coalesce(rr.receipt_id,pr.payment_id,cr.refund_id,sr.refund_id) AS original_document_id,
 (rr.id IS NOT NULL OR pr.id IS NOT NULL OR cr.id IS NOT NULL OR sr.id IS NOT NULL) AS is_reversal,
 ((b.posting_kind='CUSTOMER_RECEIPT' AND EXISTS(SELECT 1 FROM accounting.customer_receipts r WHERE r.company_id=l.company_id AND r.id=b.source_document_id AND r.bank_account_id=l.account_id)) OR
 (b.posting_kind='SUPPLIER_PAYMENT' AND EXISTS(SELECT 1 FROM accounting.supplier_payments p WHERE p.company_id=l.company_id AND p.id=b.source_document_id AND p.bank_account_id=l.account_id)) OR
 (b.posting_kind='CUSTOMER_REFUND' AND EXISTS(SELECT 1 FROM accounting.customer_refunds f WHERE f.company_id=l.company_id AND f.id=b.source_document_id)) OR
 (b.posting_kind='SUPPLIER_REFUND' AND EXISTS(SELECT 1 FROM accounting.supplier_refunds f WHERE f.company_id=l.company_id AND f.id=b.source_document_id AND f.bank_account_id=l.account_id))) AS trade_source,
 NOT EXISTS(SELECT 1 FROM accounting.journal_lines other LEFT JOIN accounting.cash_flow_scopes sc ON sc.company_id=other.company_id AND sc.bank_account_id=other.account_id WHERE other.company_id=l.company_id AND other.journal_entry_id=j.id AND(other.debit<>0 OR other.credit<>0)AND coalesce(sc.included,false)=false) AS pure_transfer
 FROM accounting.journal_lines l JOIN accounting.cash_flow_scopes s ON s.company_id=l.company_id AND s.bank_account_id=l.account_id AND s.included JOIN accounting.journal_entries j ON j.company_id=l.company_id AND j.id=l.journal_entry_id JOIN accounting.posting_batches b ON b.company_id=j.company_id AND b.id=j.posting_batch_id JOIN platform.documents d ON d.company_id=b.company_id AND d.id=b.source_document_id
 LEFT JOIN accounting.receipt_reversals rr ON rr.company_id=b.company_id AND rr.id=b.source_document_id AND b.posting_kind='RECEIPT_REVERSAL'
 LEFT JOIN accounting.supplier_payment_reversals pr ON pr.company_id=b.company_id AND pr.id=b.source_document_id AND b.posting_kind='SUPPLIER_PAYMENT_REVERSAL'
 LEFT JOIN accounting.customer_refund_reversals cr ON cr.company_id=b.company_id AND cr.id=b.source_document_id AND b.posting_kind='CUSTOMER_REFUND_REVERSAL'
 LEFT JOIN accounting.supplier_refund_reversals sr ON sr.company_id=b.company_id AND sr.id=b.source_document_id AND b.posting_kind='SUPPLIER_REFUND_REVERSAL' WHERE l.debit<>l.credit;
CREATE VIEW accounting.cash_flow_latest WITH(security_invoker=true) AS SELECT DISTINCT ON(company_id,journal_entry_id) * FROM accounting.cash_flow_classifications ORDER BY company_id,journal_entry_id,revision DESC;
CREATE VIEW accounting.cash_flow_review_links WITH(security_invoker=true) AS
 WITH RECURSIVE edges AS(SELECT company_id,id AS document_id,original_receipt_id AS original_id FROM accounting.receipt_reapplications UNION ALL SELECT company_id,id,original_payment_id FROM accounting.supplier_payment_reapplications UNION ALL SELECT company_id,id,original_refund_id FROM accounting.customer_refund_corrections UNION ALL SELECT company_id,id,original_refund_id FROM accounting.supplier_refund_corrections), paths AS(SELECT company_id,document_id,original_id FROM edges UNION SELECT p.company_id,p.document_id,e.original_id FROM paths p JOIN edges e ON e.company_id=p.company_id AND e.document_id=p.original_id) SELECT * FROM paths;
CREATE VIEW accounting.cash_flow_base WITH(security_invoker=true) AS
 WITH lines AS MATERIALIZED(SELECT * FROM accounting.cash_flow_lines WHERE company_id=core.current_company()), latest AS MATERIALIZED(SELECT * FROM accounting.cash_flow_latest WHERE company_id=core.current_company()),
 reviewed AS MATERIALIZED(SELECT DISTINCT x.company_id,x.document_id FROM accounting.cash_flow_review_links x JOIN lines original ON original.company_id=x.company_id AND original.source_document_id=x.original_id JOIN latest prior ON prior.company_id=original.company_id AND prior.journal_entry_id=original.journal_entry_id AND prior.mode='CUSTOM' WHERE x.company_id=core.current_company())
 SELECT l.company_id,l.id AS journal_line_id,a.category,a.amount,sign(l.signed_amount)*a.amount AS signed_amount,c.revision,'CUSTOM'::text AS basis FROM lines l JOIN latest c ON c.company_id=l.company_id AND c.journal_entry_id=l.journal_entry_id AND c.mode='CUSTOM' JOIN accounting.cash_flow_allocations a ON a.company_id=c.company_id AND a.classification_id=c.id AND a.journal_line_id=l.id
 UNION ALL
 SELECT l.company_id,l.id,CASE WHEN l.pure_transfer THEN 'INTERNAL' WHEN l.trade_source AND rv.document_id IS NULL THEN 'OPERATING' ELSE 'UNCLASSIFIED' END,l.amount,l.signed_amount,coalesce(c.revision,0),'AUTO' FROM lines l LEFT JOIN latest c ON c.company_id=l.company_id AND c.journal_entry_id=l.journal_entry_id LEFT JOIN reviewed rv ON rv.company_id=l.company_id AND rv.document_id=l.source_document_id WHERE c.id IS NULL OR c.mode='AUTO';
CREATE VIEW accounting.cash_flow_effective WITH(security_invoker=true) AS
 WITH lines AS MATERIALIZED(SELECT * FROM accounting.cash_flow_lines WHERE company_id=core.current_company()), base AS MATERIALIZED(SELECT * FROM accounting.cash_flow_base WHERE company_id=core.current_company())
 SELECT b.* FROM base b JOIN lines l ON l.company_id=b.company_id AND l.id=b.journal_line_id WHERE NOT l.is_reversal
 UNION ALL
 SELECT r.company_id,r.id,b.category,b.amount,-b.signed_amount,b.revision,'REVERSAL_INHERITED' FROM lines r JOIN lines original ON original.company_id=r.company_id AND original.source_document_id=r.original_document_id AND original.bank_account_id=r.bank_account_id AND original.signed_amount=-r.signed_amount AND NOT original.is_reversal JOIN base b ON b.company_id=original.company_id AND b.journal_line_id=original.id WHERE r.is_reversal
 UNION ALL
 SELECT r.company_id,r.id,'UNCLASSIFIED',r.amount,r.signed_amount,0,'REVERSAL_SOURCE_MISSING' FROM lines r WHERE r.is_reversal AND NOT EXISTS(SELECT 1 FROM lines original WHERE original.company_id=r.company_id AND original.source_document_id=r.original_document_id AND original.bank_account_id=r.bank_account_id AND original.signed_amount=-r.signed_amount AND NOT original.is_reversal);
CREATE FUNCTION accounting.classify_cash_flow(journal uuid,expected bigint,p_mode text,p_reason text,items jsonb) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$ DECLARE c uuid:=core.current_company();rev bigint;cid uuid:=gen_random_uuid();x jsonb;BEGIN
 PERFORM accounting.require_cash_flow_access('accounting.cash_flow.classify');PERFORM pg_advisory_xact_lock(hashtextextended('cash-flow:'||c::text||':'||journal::text,0));
 IF NOT EXISTS(SELECT 1 FROM accounting.cash_flow_lines WHERE company_id=c AND journal_entry_id=journal) THEN RAISE EXCEPTION 'Cash journal unavailable' USING ERRCODE='HT404';END IF;
 IF EXISTS(SELECT 1 FROM accounting.journal_lines l JOIN accounting.cash_flow_scopes sc ON sc.company_id=l.company_id AND sc.bank_account_id=l.account_id WHERE l.company_id=c AND l.journal_entry_id=journal AND sc.review_required) THEN RAISE EXCEPTION 'Confirm migrated cash-equivalent scope before classifying' USING ERRCODE='HR409';END IF;
 IF EXISTS(SELECT 1 FROM accounting.cash_flow_lines WHERE company_id=c AND journal_entry_id=journal AND is_reversal) THEN RAISE EXCEPTION 'Classify the original cash journal; reversal inherits its classification' USING ERRCODE='HR409';END IF;
 SELECT coalesce(max(revision),0) INTO rev FROM accounting.cash_flow_classifications WHERE company_id=c AND journal_entry_id=journal;
 IF expected IS NULL OR expected<>rev THEN RAISE EXCEPTION 'Cash classification changed' USING ERRCODE='HR409';END IF;
 IF p_mode IS NULL OR p_mode NOT IN('AUTO','CUSTOM') OR p_reason IS NULL OR length(btrim(p_reason)) NOT BETWEEN 1 AND 2000 OR items IS NULL OR jsonb_typeof(items)<>'array' OR jsonb_array_length(items)>100 OR(p_mode='AUTO' AND jsonb_array_length(items)<>0) OR(p_mode='CUSTOM' AND jsonb_array_length(items)=0) THEN RAISE EXCEPTION 'Mode, reason and allocations required' USING ERRCODE='HR422';END IF;
 INSERT INTO accounting.cash_flow_classifications(id,company_id,journal_entry_id,revision,mode,reason,created_by) VALUES(cid,c,journal,rev+1,p_mode,btrim(p_reason),core.current_actor());
 FOR x IN SELECT * FROM jsonb_array_elements(items) LOOP
 IF (x->>'amount')::numeric IS NULL OR (x->>'amount')::numeric<=0 OR (x->>'amount')::numeric<>round((x->>'amount')::numeric,2) THEN RAISE EXCEPTION 'Positive AUD cents required' USING ERRCODE='HR422';END IF;
 INSERT INTO accounting.cash_flow_allocations(company_id,classification_id,journal_line_id,category,amount) VALUES(c,cid,(x->>'journalLineId')::uuid,x->>'category',(x->>'amount')::numeric);END LOOP;RETURN cid;END $$;
CREATE FUNCTION accounting.validate_cash_flow_classification() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$ DECLARE c uuid:=NEW.company_id;cid uuid;h accounting.cash_flow_classifications;BEGIN
 IF TG_TABLE_NAME='cash_flow_classifications' THEN cid:=NEW.id;ELSE cid:=NEW.classification_id;END IF;SELECT * INTO h FROM accounting.cash_flow_classifications WHERE company_id=c AND id=cid;
 IF h.mode='AUTO' AND EXISTS(SELECT 1 FROM accounting.cash_flow_allocations WHERE company_id=c AND classification_id=cid) THEN RAISE EXCEPTION 'AUTO classification cannot allocate' USING ERRCODE='23514';END IF;
 IF h.mode='CUSTOM' AND(
 NOT EXISTS(SELECT 1 FROM accounting.cash_flow_lines WHERE company_id=c AND journal_entry_id=h.journal_entry_id) OR EXISTS(SELECT 1 FROM accounting.cash_flow_lines WHERE company_id=c AND journal_entry_id=h.journal_entry_id AND is_reversal) OR
 EXISTS(SELECT 1 FROM accounting.cash_flow_allocations a LEFT JOIN accounting.cash_flow_lines l ON l.company_id=a.company_id AND l.id=a.journal_line_id WHERE a.company_id=c AND a.classification_id=cid AND(l.id IS NULL OR l.journal_entry_id<>h.journal_entry_id OR(l.pure_transfer AND a.category<>'INTERNAL'))) OR
 EXISTS(SELECT 1 FROM accounting.cash_flow_lines l WHERE l.company_id=c AND l.journal_entry_id=h.journal_entry_id AND l.amount<>(SELECT coalesce(sum(a.amount),0) FROM accounting.cash_flow_allocations a WHERE a.company_id=c AND a.classification_id=cid AND a.journal_line_id=l.id)) OR
 (SELECT coalesce(sum(sign(l.signed_amount)*a.amount),0) FROM accounting.cash_flow_allocations a JOIN accounting.cash_flow_lines l ON l.company_id=a.company_id AND l.id=a.journal_line_id WHERE a.company_id=c AND a.classification_id=cid AND a.category='INTERNAL')<>0) THEN RAISE EXCEPTION 'Cash allocation source, coverage or internal-transfer balance invalid' USING ERRCODE='HR422';END IF;RETURN NULL;END $$;
CREATE CONSTRAINT TRIGGER cash_flow_consistency AFTER INSERT ON accounting.cash_flow_classifications DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION accounting.validate_cash_flow_classification();
CREATE CONSTRAINT TRIGGER cash_flow_consistency AFTER INSERT ON accounting.cash_flow_allocations DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION accounting.validate_cash_flow_classification();
GRANT SELECT ON accounting.cash_flow_scopes,accounting.cash_flow_classifications,accounting.cash_flow_allocations,accounting.cash_flow_review_links,accounting.cash_flow_lines,accounting.cash_flow_latest,accounting.cash_flow_base,accounting.cash_flow_effective TO htt_app;
REVOKE ALL ON FUNCTION identity.seed_cash_flow_roles(uuid),accounting.synchronize_cash_scope(),accounting.require_cash_flow_access(text),accounting.configure_cash_scope(uuid,bigint,boolean,text),accounting.guard_cash_scope_posting(),accounting.classify_cash_flow(uuid,bigint,text,text,jsonb),accounting.validate_cash_flow_classification() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION accounting.require_cash_flow_access(text),accounting.configure_cash_scope(uuid,bigint,boolean,text),accounting.classify_cash_flow(uuid,bigint,text,text,jsonb) TO htt_app;
CREATE INDEX ON accounting.cash_flow_allocations(company_id,journal_line_id);
